begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(22);
insert into public.clinics(id,name) values('c1000000-0000-4000-8000-000000000001','Synthetic Schedule A'),('c1000000-0000-4000-8000-000000000002','Synthetic Schedule B');
insert into auth.users(id) values('c2000000-0000-4000-8000-000000000001'),('c2000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','reception',true),('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','manager',true);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source) values('c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','Synthetic Contact','phone');
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
create function pg_temp.schedule(p jsonb,k uuid default 'c4000000-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.set_inquiry_follow_up_schedule('c1000000-0000-4000-8000-000000000001','c3000000-0000-4000-8000-000000000001',k,p,'c5000000-0000-4000-8000-000000000001')$$;
select ok(not has_function_privilege('anon','public.set_inquiry_follow_up_schedule(uuid,uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous execution denied');
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}')$$,'PT503',null,'database default-off');
update private.intake_command_settings set enabled=true;
set local role authenticated;
select is(pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":"2026-11-02T10:00:00.123456Z"}')->'receipt'->>'follow_up_at','2026-11-02T10:00:00.123456Z','exact microseconds saved');
select is((pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":"2026-11-02T11:00:00.123456+01:00"}')->>'replayed')::boolean,true,'equivalent offset exact replay');
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}')$$,'PT409',null,'key payload conflict');
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}','c4000000-0000-4000-8000-000000000002')$$,'PT409',null,'stale null CAS conflicts');
select is((pg_temp.schedule('{"expected_follow_up_at":"2026-11-02T10:00:00.123456Z","follow_up_at":"2026-11-02T10:00:00.123456Z"}','c4000000-0000-4000-8000-000000000002')->'receipt'->>'changed')::boolean,false,'no-op produces receipt');
reset role;
select is((select count(*)::int from private.audit_events where clinic_id='c1000000-0000-4000-8000-000000000001'),1,'no-op and replay emit no audit');
select is((select count(*)::int from private.inquiry_schedule_receipts where clinic_id='c1000000-0000-4000-8000-000000000001'),2,'no-op receipt durable');
select is((select count(*)::int from private.outbox_events e cross join lateral jsonb_object_keys(e.payload) where e.clinic_id='c1000000-0000-4000-8000-000000000001'),3,'minimal three-field event payload');
select throws_ok($$update private.inquiry_schedule_receipts set receipt='{}' where clinic_id='c1000000-0000-4000-8000-000000000001'$$,'55000',null,'receipt update forbidden');
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}')$$,'PT404',null,'other manager cannot modify owner deadline');
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000001',true);
update public.inquiries set owner_user_id='c2000000-0000-4000-8000-000000000002' where id='c3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":"2026-11-02T10:00:00.123456Z"}')$$,'PT404',null,'former owner cannot replay');
update public.inquiries set owner_user_id='c2000000-0000-4000-8000-000000000001' where id='c3000000-0000-4000-8000-000000000001';
update private.intake_command_settings set enabled=false;
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":"2026-11-02T10:00:00.123456Z"}')$$,'PT503',null,'disabled receipt replay denied');
update private.intake_command_settings set enabled=true;
update public.clinic_memberships set role='assistant' where user_id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}')$$,'42501',null,'privileged assistant denied');
update public.clinic_memberships set role='reception',active=false where user_id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":null}')$$,'42501',null,'inactive owner denied');
update public.clinic_memberships set active=true where user_id='c2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.set_inquiry_follow_up_schedule('c1000000-0000-4000-8000-000000000002','c3000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"expected_follow_up_at":null,"follow_up_at":null}',gen_random_uuid())$$,'PT404',null,'cross-clinic target hidden');
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":null,"follow_up_at":"2026-01-01T00:00:00.1234567Z"}',gen_random_uuid())$$,'22023',null,'reject precision rounding');
select throws_ok($$select private.inquiry_schedule_instant('"0001-01-01T00:00:00+01:00"')$$,'22023',null,'UTC lower range enforced');
select is(private.inquiry_schedule_instant('"9999-12-31T23:59:59.999999Z"'),'9999-12-31T23:59:59.999999Z'::timestamptz,'upper microsecond accepted');
create function pg_temp.fail_schedule_sink() returns trigger language plpgsql as $$begin raise exception 'synthetic sink failure';end$$;
create trigger fail_schedule_sink before insert on private.outbox_events for each row execute function pg_temp.fail_schedule_sink();
select throws_ok($$select pg_temp.schedule('{"expected_follow_up_at":"2026-11-02T10:00:00.123456Z","follow_up_at":null}',gen_random_uuid())$$,'P0001','synthetic sink failure','sink failure aborts command');
select is((select follow_up_at from public.inquiries where id='c3000000-0000-4000-8000-000000000001'),'2026-11-02T10:00:00.123456Z'::timestamptz,'deadline rolls back with sink');
select * from finish();
rollback;
